+    {
+      handle_ack(&message);
+      leave_critical_section(flags);
+      return;
+    }
+
+  if (logical_channel != MB_CHNL_PWC_RX)
+    {
+      g_stats.bad_envelope++;
+      leave_critical_section(flags);
+      return;
+    }
